package com.hibernate.ecommerce.model;import jakarta.persistence.*;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.NotNull;import lombok.*;import org.hibernate.annotations.CreationTimestamp;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;@Entity@Getter @Setter@AllArgsConstructor@NoArgsConstructor@Builder@Table(name = "orders")public class Order {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @Enumerated(EnumType.STRING)    private state state;    @CreationTimestamp    private LocalDateTime registerDate;    @ManyToOne    private Client client;    @OneToMany(mappedBy = "order", fetch = FetchType.LAZY, cascade = CascadeType.ALL)    List<Orderdetails> orderdetails = new ArrayList<>();}